SELECT 'batch_026_22c0a8f2_wav_10' AS batch_id,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-205b475a8daa49e7aac80f692e08ef85','sm-77217bc2bfde468a9df2c5898f54cfbf','sm-cb51493104794550b49f7988b8d268e5','sm-upload-0243c28d-146','sm-upload-0bbfaed5-aa8','sm-upload-2913df11-776','sm-upload-4a6b97de-6d6','sm-upload-5d55b9ac-edb','sm-upload-67747466-85e','sm-upload-e6ce4e4e-0b8') AND album_id='al-a3063d83f8e97bbb84445eef22c0a8f2') AS candidate_masters_in_target,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-205b475a8daa49e7aac80f692e08ef85','sm-77217bc2bfde468a9df2c5898f54cfbf','sm-cb51493104794550b49f7988b8d268e5','sm-upload-0243c28d-146','sm-upload-0bbfaed5-aa8','sm-upload-2913df11-776','sm-upload-4a6b97de-6d6','sm-upload-5d55b9ac-edb','sm-upload-67747466-85e','sm-upload-e6ce4e4e-0b8') AND album_id='pending-uploads') AS candidate_masters_still_pending,(SELECT COUNT(*) FROM albums WHERE id='al-a3063d83f8e97bbb84445eef22c0a8f2' AND name='回声漫过荒原') AS target_album_rows,(SELECT song_count FROM albums WHERE id='al-a3063d83f8e97bbb84445eef22c0a8f2') AS stored_song_count,(SELECT COALESCE(SUM(si.size),0) FROM song_instances si JOIN song_masters sm ON sm.id=si.master_id WHERE sm.album_id='al-a3063d83f8e97bbb84445eef22c0a8f2') AS calculated_size;
